/**
 * Brand mark: square brackets around a source block, like an inline citation.
 * Same geometry as public/favicon.svg (generated by scripts/favicon.mjs).
 */
export const LOGO_PATHS = {
  brackets: "M12.5 9H9.5V23H12.5M19.5 9H22.5V23H19.5",
  block: { x: 13.75, y: 13.75, size: 4.5, radius: 1 },
};

export function Logo({ size = 24 }: { size?: number }) {
  const { brackets, block } = LOGO_PATHS;
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" aria-hidden className="shrink-0">
      <rect width="32" height="32" rx="8" className="fill-accent" />
      <path d={brackets} fill="none" strokeWidth="2.25" strokeLinecap="square" className="stroke-accent-fg" />
      <rect x={block.x} y={block.y} width={block.size} height={block.size} rx={block.radius} className="fill-accent-fg" />
    </svg>
  );
}
